// Compare live DB columns vs Sequelize model definitions.
process.chdir('C:/Users/felth/Downloads/FlowGuard/server');
require('dotenv').config({ path: 'C:/Users/felth/Downloads/FlowGuard/server/.env' });
const db = require('C:/Users/felth/Downloads/FlowGuard/server/models');

(async () => {
  const qi = db.sequelize.getQueryInterface();
  const names = Object.keys(db).filter(k => k !== 'sequelize' && k !== 'Sequelize');
  let issues = 0;
  for (const name of names) {
    const model = db[name];
    const table = model.getTableName();
    let actual;
    try {
      actual = await qi.describeTable(table);
    } catch (e) {
      console.log(`MISSING TABLE: ${table} (${name})`);
      issues++;
      continue;
    }
    const expected = Object.values(model.rawAttributes)
      .map(a => a.field || a.fieldName)
      .filter(Boolean);
    const actualCols = Object.keys(actual);
    const missing = expected.filter(c => !actualCols.includes(c));
    const extra = actualCols.filter(c => !expected.includes(c));
    if (missing.length) { console.log(`${name} (${table}) MISSING COLUMNS: ${missing.join(', ')}`); issues++; }
    if (extra.length) console.log(`${name} (${table}) extra columns in DB: ${extra.join(', ')}`);
  }
  console.log(issues ? `\n${issues} issue(s) found.` : '\nSchema matches models. No missing tables/columns.');
  await db.sequelize.close();
})().catch(e => { console.error('ERROR:', e.message); process.exit(1); });

